MERGE `{{params.project_name}}.semantics_central.CarPricing` final
USING (
{{range_query}}
) staging
ON final.car_pricing_id = staging.car_pricing_id
WHEN MATCHED THEN
UPDATE SET
	final.car_id = staging.car_id,
    final.type = staging.type,
    final.amount = staging.amount,
    final.amount_usd = staging.amount_usd,
    final.subtype = staging.subtype,
    final.comments = staging.comments,
    final.country_id = staging.country_id,
    final.vat_percentage = staging.vat_percentage,
    final.vat = staging.vat,
    final.vat_usd = staging.vat_usd,
	final.created_at = staging.created_at,
	final.updated_at = staging.updated_at,
	final.deleted_at = staging.deleted_at,
    final.created_by_email = staging.created_by_email,
    final.created_by_id = staging.created_by_id,
    final.updated_by_id = staging.updated_by_id,
    final.updated_by_email = staging.updated_by_email,
    final.deleted_by_id = staging.deleted_by_id,
    final.created_by = staging.created_by,
    final.updated_by = staging.updated_by,
    final.deleted_by = staging.deleted_by,
    final.reference_id = staging.reference_id,
    final.entity = staging.entity
WHEN NOT MATCHED THEN
INSERT (
    car_pricing_id,
    car_id,
    type,
    amount,
    amount_usd,
    subtype,
    comments,
    country_id,
    vat_percentage,
    vat,
    vat_usd,
	created_at,
	updated_at,
	deleted_at,
    created_by_email,
    created_by_id,
    updated_by_id,
    updated_by_email,
    deleted_by_id,
    created_by,
    updated_by,
    deleted_by,
    reference_id,
    entity
) VALUES (
    staging.car_pricing_id,
    staging.car_id,
    staging.type,
    staging.amount,
    staging.amount_usd,
    staging.subtype,
    staging.comments,
    staging.country_id,
    staging.vat_percentage,
    staging.vat,
    staging.vat_usd,
	staging.created_at,
	staging.updated_at,
	staging.deleted_at,
    staging.created_by_email,
    staging.created_by_id,
    staging.updated_by_id,
    staging.updated_by_email,
    staging.deleted_by_id,
    staging.created_by,
    staging.updated_by,
    staging.deleted_by,
    staging.reference_id,
    staging.entity
)